(10, 1, 2, 'Python Programming Essentials', 'PY-101', 'Computer Science', 'Learn Python programming from the fundamentals through practical programming exercises.', '[\"Understand Python syntax\",\"Work with variables and data types\",\"Use functions and control flow\",\"Build small Python programs\"]', 'https://images.unsplash.com/photo-1526379095098-d400fd0bf935?w=800&q=80', 'Beginner', 6, 0.00, 100, 1, 'published', '2026-10-03 23:41:03', '2026-10-03 23:41:03'),
(11, 2, 2, 'Web Development with React', 'REACT-201', 'Computer Science', 'Build modern interactive web applications using React and component-based development.', '[\"Understand React fundamentals\",\"Create reusable components\",\"Manage state and events\",\"Build interactive web interfaces\"]', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=800&q=80', 'Intermediate', 8, 0.00, 100, 1, 'published', '2026-10-03 23:41:03', '2026-10-03 23:41:03'),
(12, 3, 2, 'Database Management System', 'DBMS-301', 'Computer Science', 'Learn relational databases, SQL queries, database design and normalization.', '[\"Understand relational databases\",\"Write SQL queries\",\"Design database schemas\",\"Understand normalization and relationships\"]', 'https://images.unsplash.com/photo-1544383835-bda2bc66a55d?w=800&q=80', 'Intermediate', 7, 0.00, 100, 1, 'published', '2026-10-03 23:41:03', '2026-10-03 23:41:03'),
(13, 1, 2, 'Java Spring Boot Development', 'SPRING-401', 'Computer Science', 'Learn to build modern backend applications and REST APIs using Java and Spring Boot.', '[\"Understand Spring Boot architecture\",\"Build REST APIs\",\"Work with Spring Data JPA\",\"Connect applications with MySQL\"]', 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?w=800&q=80', 'Intermediate', 8, 0.00, 100, 1, 'published', '2026-10-03 23:46:59', '2026-10-03 23:46:59'),
(14, 1, 2, 'Data Structures and Algorithms', 'DSA-402', 'Computer Science', 'Master fundamental data structures and algorithms used in software development.', '[\"Understand common data structures\",\"Analyze algorithm complexity\",\"Implement searching and sorting\",\"Solve algorithmic problems\"]', 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=800&q=80', 'Intermediate', 10, 0.00, 100, 1, 'published', '2026-10-03 23:46:59', '2026-10-03 23:46:59'),
(15, 4, 2, 'Software Engineering', 'SE-403', 'Computer Science', 'Learn software development processes, requirements, design, testing and project management.', '[\"Understand SDLC models\",\"Write software requirements\",\"Design software systems\",\"Apply software testing techniques\"]', 'https://images.unsplash.com/photo-1556761175-b413da4baf72?w=800&q=80', 'Intermediate', 8, 0.00, 100, 1, 'published', '2026-10-03 23:46:59', '2026-10-03 23:46:59'),
(16, 5, 2, 'Artificial Intelligence Fundamentals', 'AI-404', 'Computer Science', 'Introduction to artificial intelligence, machine learning concepts and intelligent problem solving.', '[\"Understand AI fundamentals\",\"Learn search algorithms\",\"Understand machine learning basics\",\"Build simple intelligent systems\"]', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=800&q=80', 'Intermediate', 9, 0.00, 100, 1, 'published', '2026-10-03 23:46:59', '2026-10-03 23:46:59'),
