(1, 1, NULL, 'Getting Started', 'Lesson 1', 'Content for Getting Started', NULL, 1, '2026-10-01 13:37:52'),
(2, 1, NULL, 'Variables & Types', 'Lesson 2', 'Content for Variables & Types', NULL, 2, '2026-10-01 13:37:52'),
(3, 1, NULL, 'Functions', 'Lesson 3', 'Content for Functions', NULL, 3, '2026-10-01 13:37:52'),
(4, 1, NULL, 'Working with the DOM', 'Lesson 4', 'Content for Working with the DOM', NULL, 4, '2026-10-01 13:37:52'),
(5, 2, NULL, 'SELECT Basics', 'Intro to SELECT', NULL, NULL, 1, '2026-10-01 13:37:52'),
(6, 2, NULL, 'Joins', 'INNER/LEFT joins', NULL, NULL, 2, '2026-10-01 13:37:52'),
(8, 9, 2, 'firstlessonss', NULL, NULL, NULL, 1, '2026-10-03 19:53:45'),
(21, 10, NULL, 'Python Basics', 'Introduction to Python programming.', 'Learn Python syntax, variables, data types and basic input/output.', 'https://www.youtube.com/watch?v=kqtD5dpn9C8', 1, '2026-10-03 23:41:03'),
(22, 10, NULL, 'Control Flow and Functions', 'Learn conditions, loops and functions.', 'Learn if-else statements, loops, parameters, return values and reusable functions.', 'https://www.youtube.com/results?search_query=Python+functions+loops+tutorial', 2, '2026-10-03 23:41:03'),
(23, 10, NULL, 'Lists, Dictionaries and Files', 'Work with Python collections and files.', 'Learn lists, dictionaries, tuples and basic file handling.', 'https://www.youtube.com/results?search_query=Python+lists+dictionaries+tutorial', 3, '2026-10-03 23:41:03'),
(24, 11, NULL, 'React Fundamentals', 'Introduction to React and components.', 'Learn React concepts, JSX, components and props.', 'https://www.youtube.com/results?search_query=React+JS+for+beginners', 1, '2026-10-03 23:41:03'),
(25, 11, NULL, 'State and Events', 'Learn state management and event handling.', 'Learn useState, event handling and interactive components.', 'https://www.youtube.com/results?search_query=React+useState+tutorial', 2, '2026-10-03 23:41:03'),
(26, 11, NULL, 'Building a React Application', 'Build a complete small React application.', 'Combine components, state and events to create a functional React application.', 'https://www.youtube.com/results?search_query=React+project+tutorial', 3, '2026-10-03 23:41:03'),
(27, 12, NULL, 'Database Fundamentals', 'Introduction to relational databases.', 'Learn databases, tables, records, primary keys and foreign keys.', 'https://www.youtube.com/results?search_query=DBMS+database+fundamentals', 1, '2026-10-03 23:41:03'),
(28, 12, NULL, 'SQL Queries', 'Learn SQL commands and queries.', 'Practice SELECT, INSERT, UPDATE, DELETE, WHERE and ORDER BY.', 'https://www.youtube.com/results?search_query=SQL+tutorial+for+beginners', 2, '2026-10-03 23:41:03'),
(29, 12, NULL, 'Database Design and Normalization', 'Learn database design principles.', 'Learn relationships, ER concepts and database normalization.', 'https://www.youtube.com/results?search_query=database+normalization+tutorial', 3, '2026-10-03 23:41:03'),
(30, 13, NULL, 'Spring Boot Fundamentals', 'Introduction to Spring Boot and project structure.', 'Learn Spring Boot architecture, dependency injection, starters and application configuration.', 'https://www.youtube.com/results?search_query=Spring+Boot+tutorial+for+beginners', 1, '2026-10-03 23:46:59'),
(31, 13, NULL, 'Building REST APIs', 'Create RESTful APIs with Spring Boot.', 'Learn controllers, HTTP methods, request mapping and JSON responses.', 'https://www.youtube.com/results?search_query=Spring+Boot+REST+API+tutorial', 2, '2026-10-03 23:46:59'),
(32, 13, NULL, 'Spring Data JPA', 'Work with databases using JPA.', 'Learn entities, repositories, relationships and CRUD operations using Spring Data JPA.', 'https://www.youtube.com/results?search_query=Spring+Data+JPA+tutorial', 3, '2026-10-03 23:46:59'),
(33, 13, NULL, 'Spring Boot Project', 'Build a complete backend application.', 'Combine REST APIs, JPA, validation and MySQL into a complete backend project.', 'https://www.youtube.com/results?search_query=Spring+Boot+full+project', 4, '2026-10-03 23:46:59'),
(34, 14, NULL, 'Arrays and Linked Lists', 'Learn linear data structures.', 'Understand arrays, singly linked lists, doubly linked lists and their operations.', 'https://www.youtube.com/results?search_query=data+structures+arrays+linked+lists', 1, '2026-10-03 23:46:59'),
(35, 14, NULL, 'Stacks and Queues', 'Learn stack and queue data structures.', 'Implement stacks and queues and understand their real-world applications.', 'https://www.youtube.com/results?search_query=stack+queue+data+structure', 2, '2026-10-03 23:46:59'),
(36, 14, NULL, 'Searching and Sorting', 'Learn important searching and sorting algorithms.', 'Study linear search, binary search, bubble sort, merge sort and quick sort.', 'https://www.youtube.com/results?search_query=sorting+algorithms+tutorial', 3, '2026-10-03 23:46:59'),
(37, 14, NULL, 'Trees and Graphs', 'Introduction to non-linear data structures.', 'Learn binary trees, traversal techniques and basic graph concepts.', 'https://www.youtube.com/results?search_query=trees+graphs+data+structures', 4, '2026-10-03 23:46:59'),
(38, 15, NULL, 'Software Development Life Cycle', 'Understand the software development lifecycle.', 'Learn SDLC phases and common development models including Waterfall and Agile.', 'https://www.youtube.com/results?search_query=software+development+life+cycle', 1, '2026-10-03 23:46:59'),
(39, 15, NULL, 'Requirements Engineering', 'Learn how to identify and document requirements.', 'Study functional requirements, non-functional requirements and use cases.', 'https://www.youtube.com/results?search_query=requirements+engineering+tutorial', 2, '2026-10-03 23:46:59'),
(40, 15, NULL, 'Software Design', 'Learn software architecture and design principles.', 'Understand modular design, architecture, UML and design patterns.', 'https://www.youtube.com/results?search_query=software+design+UML+tutorial', 3, '2026-10-03 23:46:59'),
(41, 15, NULL, 'Software Testing', 'Introduction to software testing.', 'Learn unit testing, integration testing, system testing and test case design.', 'https://www.youtube.com/results?search_query=software+testing+tutorial', 4, '2026-10-03 23:46:59'),
(42, 16, NULL, 'Introduction to Artificial Intelligence', 'Basic concepts of AI.', 'Learn the history, goals, applications and major areas of artificial intelligence.', 'https://www.youtube.com/results?search_query=artificial+intelligence+introduction', 1, '2026-10-03 23:46:59'),
(43, 16, NULL, 'Search Algorithms', 'Learn how AI agents solve problems using search.', 'Study BFS, DFS, Uniform Cost Search and A* search.', 'https://www.youtube.com/results?search_query=AI+search+algorithms+A+star', 2, '2026-10-03 23:46:59'),
(44, 16, NULL, 'Machine Learning Basics', 'Introduction to machine learning.', 'Learn supervised learning, unsupervised learning and basic model training concepts.', 'https://www.youtube.com/results?search_query=machine+learning+basics', 3, '2026-10-03 23:46:59'),
(45, 16, NULL, 'AI Mini Project', 'Apply AI concepts in a practical project.', 'Build a simple intelligent application using a suitable AI technique.', 'https://www.youtube.com/results?search_query=AI+project+tutorial', 4, '2026-10-03 23:46:59'),
(46, 17, 3, 'juju', 'hghsfxasgxah', 'hgdyatsdafsgxv', 'https://youtu.be/B0lltMFTfv8?si=KbobP4Dq4U4kpSKJ', 1, '2026-10-04 01:10:58'),
(47, 19, NULL, 'Introduction to HTML', 'Understand the structure of an HTML document.', 'HTML provides the structure of a web page. Learn about elements, attributes, headings, paragraphs, links and semantic structure.', NULL, 1, '2026-10-04 12:10:43'),
(48, 19, NULL, 'HTML Forms', 'Learn how forms collect user information.', 'Study form elements such as input, label, textarea, select and button. Learn how forms are structured for usability and accessibility.', NULL, 2, '2026-10-04 12:10:43'),
(49, 19, NULL, 'CSS Selectors', 'Learn how CSS targets HTML elements.', 'Explore element, class, ID, attribute and pseudo-class selectors. Practice combining selectors to style pages efficiently.', NULL, 3, '2026-10-04 12:10:43'),
(50, 19, NULL, 'Flexbox Layout', 'Build flexible page layouts with CSS Flexbox.', 'Learn flex containers, main axis, cross axis, gap, alignment, wrapping and common responsive layout patterns.', NULL, 4, '2026-10-04 12:10:43'),
(51, 19, NULL, 'Responsive Web Design', 'Make web pages adapt to different screen sizes.', 'Learn media queries, responsive units and mobile-first design. Build layouts that work across phones, tablets and desktops.', NULL, 5, '2026-10-04 12:10:43'),
(52, 20, NULL, 'JavaScript Basics', 'Learn variables, data types and operators.', 'Understand let, const, strings, numbers, booleans, arrays and basic operators used in JavaScript programs.', NULL, 1, '2026-10-04 12:10:43'),
(53, 20, NULL, 'Functions', 'Organize JavaScript logic using reusable functions.', 'Learn function declarations, parameters, return values, arrow functions and scope.', NULL, 2, '2026-10-04 12:10:43'),
(54, 20, NULL, 'DOM Manipulation', 'Control web page elements using JavaScript.', 'Learn how to select elements, change text and classes, create elements and update the page dynamically.', NULL, 3, '2026-10-04 12:10:43'),
(55, 20, NULL, 'Events', 'Make web pages respond to user actions.', 'Study click, submit, input and keyboard events. Learn event listeners and basic event handling patterns.', NULL, 4, '2026-10-04 12:10:43'),
(56, 20, NULL, 'Async JavaScript', 'Understand asynchronous operations and APIs.', 'Learn promises, async/await, fetch and how frontend applications communicate with backend APIs.', NULL, 5, '2026-10-04 12:10:43'),
(57, 21, NULL, 'Python Syntax', 'Learn the basic syntax of Python.', 'Understand indentation, variables, data types, operators and simple input/output.', NULL, 1, '2026-10-04 12:10:43'),
(58, 21, NULL, 'Conditions and Loops', 'Control program execution.', 'Practice if/elif/else conditions, for loops, while loops and common loop patterns.', NULL, 2, '2026-10-04 12:10:43'),
(59, 21, NULL, 'Functions in Python', 'Create reusable blocks of Python code.', 'Learn parameters, return values, default arguments and basic function design.', NULL, 3, '2026-10-04 12:10:43'),
(60, 21, NULL, 'Lists and Dictionaries', 'Work with Python collections.', 'Practice lists, tuples, sets and dictionaries with common operations and iteration techniques.', NULL, 4, '2026-10-04 12:10:43'),
(61, 21, NULL, 'File Handling', 'Read and write files using Python.', 'Learn file modes, reading text, writing files and using context managers safely.', NULL, 5, '2026-10-04 12:10:43'),
(62, 22, NULL, 'Arrays and Lists', 'Understand linear data structures.', 'Explore arrays and Python lists, indexing, insertion, deletion and traversal.', NULL, 1, '2026-10-04 12:10:43'),
(63, 22, NULL, 'Stacks and Queues', 'Learn LIFO and FIFO structures.', 'Implement stacks and queues and understand their practical applications.', NULL, 2, '2026-10-04 12:10:43'),
(64, 22, NULL, 'Linked Lists', 'Understand node-based data structures.', 'Study singly linked lists, traversal, insertion and deletion.', NULL, 3, '2026-10-04 12:10:43'),
(65, 22, NULL, 'Trees', 'Learn hierarchical data structures.', 'Understand tree terminology, binary trees and basic traversal strategies.', NULL, 4, '2026-10-04 12:10:43'),
(66, 22, NULL, 'Algorithmic Complexity', 'Analyze algorithm efficiency.', 'Learn Big O notation and compare common searching and sorting operations.', NULL, 5, '2026-10-04 12:10:43'),
(67, 23, NULL, 'Database Fundamentals', 'Understand databases and relational models.', 'Learn tables, rows, columns, primary keys, foreign keys and relationships.', NULL, 1, '2026-10-04 12:10:43'),
(68, 23, NULL, 'SQL Queries', 'Retrieve and modify database records.', 'Practice SELECT, INSERT, UPDATE, DELETE, WHERE, ORDER BY and aggregate functions.', NULL, 2, '2026-10-04 12:10:43'),
(69, 23, NULL, 'Database Design and Normalization', 'Design structured relational databases.', 'Learn functional dependencies and normalization concepts including 1NF, 2NF and 3NF.', NULL, 3, '2026-10-04 12:10:43'),
(70, 12, NULL, 'Transactions', 'Understand reliable database operations.', 'Study transactions, COMMIT, ROLLBACK and the ACID properties.', NULL, 4, '2026-10-04 12:10:43'),
(71, 23, NULL, 'Transactions', 'Understand reliable database operations.', 'Study transactions, COMMIT, ROLLBACK and the ACID properties.', NULL, 4, '2026-10-04 12:10:43'),
(72, 12, NULL, 'Indexes', 'Improve database query performance.', 'Learn indexes, common indexing strategies and when indexes improve query performance.', NULL, 5, '2026-10-04 12:10:43'),
(73, 23, NULL, 'Indexes', 'Improve database query performance.', 'Learn indexes, common indexing strategies and when indexes improve query performance.', NULL, 5, '2026-10-04 12:10:43'),
(74, 24, NULL, 'Advanced Joins', 'Master complex table joins.', 'Practice inner, left, right and self joins using realistic relational data.', NULL, 1, '2026-10-04 12:10:43'),
(75, 24, NULL, 'Subqueries', 'Use queries inside other queries.', 'Learn scalar, correlated and table subqueries.', NULL, 2, '2026-10-04 12:10:43'),
(76, 24, NULL, 'Views', 'Create reusable database views.', 'Understand how views simplify complex queries and provide controlled access to data.', NULL, 3, '2026-10-04 12:10:43'),
(77, 24, NULL, 'Indexes and Execution Plans', 'Analyze query performance.', 'Learn how indexes affect execution and how execution plans help identify slow queries.', NULL, 4, '2026-10-04 12:10:43'),
(78, 24, NULL, 'Optimization Practice', 'Apply SQL optimization techniques.', 'Compare inefficient and optimized queries and identify common performance problems.', NULL, 5, '2026-10-04 12:10:43'),
(79, 25, NULL, 'Security Principles', 'Learn confidentiality, integrity and availability.', 'Understand the CIA triad and basic security controls.', NULL, 1, '2026-10-04 12:10:43'),
(80, 25, NULL, 'Authentication', 'Understand secure user authentication.', 'Study passwords, hashing, authentication factors and session security.', NULL, 2, '2026-10-04 12:10:43'),
(81, 25, NULL, 'Common Web Attacks', 'Recognize common web security threats.', 'Learn the concepts behind SQL injection, XSS, CSRF and insecure authentication.', NULL, 3, '2026-10-04 12:10:43'),
(82, 25, NULL, 'Network Security', 'Understand basic network defense.', 'Explore firewalls, secure protocols, segmentation and monitoring.', NULL, 4, '2026-10-04 12:10:43'),
(83, 25, NULL, 'Security Best Practices', 'Build safer software and systems.', 'Review patching, least privilege, backups, logging and secure development practices.', NULL, 5, '2026-10-04 12:10:43'),
(84, 26, NULL, 'Networking Basics', 'Learn fundamental networking concepts.', 'Understand hosts, networks, protocols, packets and basic network communication.', NULL, 1, '2026-10-04 12:10:43'),
(85, 26, NULL, 'OSI and TCP/IP', 'Understand network protocol layers.', 'Study the OSI model and map common protocols to the TCP/IP stack.', NULL, 2, '2026-10-04 12:10:43'),
(86, 26, NULL, 'IP Addressing', 'Learn IPv4 addressing and subnet concepts.', 'Practice IP addresses, subnet masks, network addresses and host ranges.', NULL, 3, '2026-10-04 12:10:43'),
(87, 26, NULL, 'Routing and Switching', 'Understand how traffic moves through networks.', 'Learn the roles of routers, switches and basic routing concepts.', NULL, 4, '2026-10-04 12:10:43'),
(88, 26, NULL, 'Network Troubleshooting', 'Diagnose common connectivity problems.', 'Use structured troubleshooting and understand common causes of network failures.', NULL, 5, '2026-10-04 12:10:43'),
(89, 27, NULL, 'Data Science Workflow', 'Understand the end-to-end data science process.', 'Learn problem definition, data collection, cleaning, exploration, modeling and communication.', NULL, 1, '2026-10-04 12:10:43'),
(90, 27, NULL, 'Data Cleaning', 'Prepare messy datasets for analysis.', 'Handle missing values, duplicates, inconsistent formats and outliers.', NULL, 2, '2026-10-04 12:10:43'),
(91, 27, NULL, 'Exploratory Data Analysis', 'Discover patterns in datasets.', 'Use descriptive statistics and visual exploration to understand data distributions.', NULL, 3, '2026-10-04 12:10:43'),
(92, 27, NULL, 'Data Visualization', 'Communicate insights with charts.', 'Learn appropriate chart selection and principles for clear data visualization.', NULL, 4, '2026-10-04 12:10:43'),
(93, 27, NULL, 'Feature Engineering', 'Create useful model features.', 'Learn encoding, scaling, transformations and feature selection basics.', NULL, 5, '2026-10-04 12:10:43'),
(94, 28, NULL, 'Machine Learning Overview', 'Understand supervised and unsupervised learning.', 'Learn the major machine learning problem types and common workflow.', NULL, 1, '2026-10-04 12:10:43'),
(95, 28, NULL, 'Regression', 'Predict continuous values.', 'Study linear regression, training data, predictions and regression evaluation.', NULL, 2, '2026-10-04 12:10:43'),
(96, 28, NULL, 'Classification', 'Predict categorical outcomes.', 'Learn classification concepts, decision boundaries and common classifiers.', NULL, 3, '2026-10-04 12:10:43'),
(97, 28, NULL, 'Model Evaluation', 'Evaluate machine learning models.', 'Study accuracy, precision, recall, F1-score, ROC-AUC and confusion matrices.', NULL, 4, '2026-10-04 12:10:43'),
(98, 28, NULL, 'Overfitting and Regularization', 'Build models that generalize well.', 'Understand overfitting, underfitting, validation and regularization techniques.', NULL, 5, '2026-10-04 12:10:43'),
(99, 29, NULL, 'Software Development Lifecycle', 'Understand the software development lifecycle.', 'Study planning, requirements, design, implementation, testing and maintenance.', NULL, 1, '2026-10-04 12:10:43'),
(100, 29, NULL, 'Requirements Engineering', 'Identify and document system requirements.', 'Learn functional and non-functional requirements, stakeholders and use cases.', NULL, 2, '2026-10-04 12:10:43'),
(101, 29, NULL, 'Agile Development', 'Understand iterative software development.', 'Learn Agile principles, Scrum roles, sprints and backlog management.', NULL, 3, '2026-10-04 12:10:43'),
(102, 29, NULL, 'Software Testing', 'Build confidence through testing.', 'Study unit, integration, system and acceptance testing.', NULL, 4, '2026-10-04 12:10:43'),
(103, 29, NULL, 'Version Control', 'Manage source code changes.', 'Learn Git concepts including commits, branches, merges and collaboration.', NULL, 5, '2026-10-04 12:10:43'),
(104, 30, NULL, 'Introduction to UI/UX', 'Understand the difference between UI and UX.', 'Learn user-centered design and the relationship between usability and visual design.', NULL, 1, '2026-10-04 12:10:43'),
(105, 30, NULL, 'User Research', 'Understand users and their needs.', 'Learn interviews, observation, personas and user journey mapping.', NULL, 2, '2026-10-04 12:10:43'),
(106, 30, NULL, 'Wireframing', 'Create low-fidelity interface layouts.', 'Learn how wireframes communicate structure and user flow.', NULL, 3, '2026-10-04 12:10:43'),
(107, 30, NULL, 'Visual Hierarchy', 'Create clear and readable interfaces.', 'Study spacing, typography, contrast, alignment and visual emphasis.', NULL, 4, '2026-10-04 12:10:43'),
(108, 30, NULL, 'Prototyping and Usability', 'Test interface ideas before development.', 'Learn interactive prototypes, usability testing and iteration.', NULL, 5, '2026-10-04 12:10:43');
